{"code": "export async function main(input: { since?: string }) {
  const since = input?.since ?? "2026-09-01T00:00:00Z";
  const counts: Record<string, number> = {};
  let cursor: string | undefined = undefined;
  let pages = 0;
  let total = 0;
  let oldest: string | null = null;
  while (true) {
    const res = await sdk.github.listCommits({ since, cursor });
    pages++;
    for (const c of res.commits) {
      if (new Date(c.committedAt).getTime() < new Date(since).getTime()) continue;
      counts[c.authorEmail] = (counts[c.authorEmail] ?? 0) + 1;
      total++;
      if (oldest === null || c.committedAt < oldest) oldest = c.committedAt;
    }
    if (!res.nextCursor) break;
    cursor = res.nextCursor;
  }
  const sorted: Record<string, number> = {};
  for (const k of Object.keys(counts).sort((a, b) => counts[b] - counts[a] || a.localeCompare(b))) sorted[k] = counts[k];
  return { since, pages, total, oldest, counts: sorted };
}", "input": {}}
